  ('dd7a5003-f92a-46f8-8de1-a862639e0aaf', 'Ba Ria-Vung Tau Neighbours Support Network', 'Mạng lưới Hàng xóm hỗ trợ Bà Rịa-Vũng Tàu', 'Neighbours in Ba Ria-Vung Tau pooling essentials for households in a bad month.', 'Hàng xóm ở Bà Rịa-Vũng Tàu chung tay chia sẻ nhu yếu phẩm cho các hộ gia đình gặp khó khăn.', 'ba-ria-vung-tau', null, null, true, true, '{}'),
  ('8c6d7d23-103e-4afd-b765-46686f8fd5b5', 'Ba Ria-Vung Tau Warm Meals Kitchen', 'Bếp ăn ấm áp Bà Rịa-Vũng Tàu', 'A volunteer kitchen serving hot meals and packing food parcels in Ba Ria-Vung Tau.', 'Bếp tình nguyện nấu bữa ăn nóng và đóng gói thực phẩm cho người dân Bà Rịa-Vũng Tàu.', 'ba-ria-vung-tau', 10.438, 107.22105, true, true, '{}'),
  ('1f5a6c98-a1bc-4002-9be4-64028fc00abe', 'Ba Ria-Vung Tau School Supplies Drive', 'Chương trình đồ dùng học tập Bà Rịa-Vũng Tàu', 'Getting books, bags and stationery to schoolchildren in Ba Ria-Vung Tau.', 'Đưa sách vở, cặp và dụng cụ học tập đến học sinh ở Bà Rịa-Vũng Tàu.', 'ba-ria-vung-tau', null, null, true, true, '{}'),
  ('456df6c7-0175-497c-a967-489ceca4de20', 'Bac Ninh Youth Volunteers', 'Thanh niên tình nguyện Bắc Ninh', 'Student volunteers collecting and sorting donations across Bac Ninh.', 'Sinh viên tình nguyện thu gom và phân loại đồ quyên góp trên khắp Bắc Ninh.', 'bac-ninh', 21.19318, 106.08492, false, true, '{}'),
  ('1a648247-62c8-4630-a9da-114edefc3f11', 'Binh Dinh Flood Response Team', 'Đội ứng phó lũ Bình Định', 'Pre-positioning blankets, clean water and dry food for flood season in Binh Dinh.', 'Chuẩn bị chăn, nước sạch và thực phẩm khô cho mùa lũ ở Bình Định.', 'binh-dinh', null, null, true, true, '{}'),
  ('fa779f42-6342-4c74-8f7f-002bcc7937b5', 'Can Tho Elders Care Group', 'Nhóm chăm sóc người cao tuổi Cần Thơ', 'Supporting older people living alone in Can Tho with food, hygiene items and company.', 'Hỗ trợ người cao tuổi sống một mình ở Cần Thơ bằng thực phẩm, vật dụng vệ sinh và sự đồng hành.', 'can-tho', 10.03524, 105.77349, true, true, '{}'),
  ('ff95d789-79a0-475b-b4e5-53758ef94aaf', 'Helping Hands Dong Nai', 'Bàn tay giúp đỡ Đồng Nai', 'A small local group matching families in Dong Nai with the household goods they need.', 'Nhóm địa phương kết nối các gia đình ở Đồng Nai với đồ dùng gia đình họ đang cần.', 'dong-nai', 10.96149, 106.87273, true, true, '{}'),
  ('b9efc1f0-7716-4162-8343-2c1c4a91da9a', 'Hanoi Family Relief Circle', 'Vòng tròn cứu trợ gia đình Hà Nội', 'Helping families in Hanoi recover after storms with food, clothing and bedding.', 'Giúp các gia đình ở Hà Nội phục hồi sau bão với thực phẩm, quần áo và chăn màn.', 'hanoi', null, null, false, true, '{}'),
  ('d99ce8ae-7135-41b5-a7f5-c8c509d06df8', 'Hanoi Health & Hygiene Aid', 'Hỗ trợ y tế và vệ sinh Hà Nội', 'Hygiene kits and basic supplies for families and clinics in Hanoi.', 'Bộ vật dụng vệ sinh và nhu yếu phẩm cơ bản cho các gia đình và trạm y tế ở Hà Nội.', 'hanoi', null, null, true, true, '{}'),
  ('612d3fb9-7228-47a9-82d8-25adb09c5c36', 'Hanoi Clothing Bank', 'Ngân hàng quần áo Hà Nội', 'Clean, usable clothing collected and handed on to people in Hanoi.', 'Quần áo sạch, còn dùng được được thu gom và trao lại cho người dân Hà Nội.', 'hanoi', 20.9826, 105.7788, true, true, '{}'),
  ('21238dee-34e2-42db-b063-62c2f62501cb', 'Hanoi Harvest Share', 'Chia sẻ mùa vàng Hà Nội', 'Rice and dry goods shared with farming households in Hanoi after a poor season.', 'Chia sẻ gạo và thực phẩm khô với các hộ nông dân ở Hà Nội sau mùa vụ kém.', 'hanoi', null, null, true, true, '{}'),
  ('b2d7ec25-eec5-4861-8228-fe4ea37f75c1', 'Hanoi Shelter Partners', 'Đối tác mái ấm Hà Nội', 'Blankets, mats and basics for people staying in temporary shelters in Hanoi.', 'Chăn, chiếu và đồ dùng thiết yếu cho người ở nơi trú tạm ở Hà Nội.', 'hanoi', 20.8072, 105.71436, false, true, '{}'),
  ('a0478549-ff0a-4bff-bc10-01d272cec5db', 'Hanoi Neighbours Support Network', 'Mạng lưới Hàng xóm hỗ trợ Hà Nội', 'Neighbours in Hanoi pooling essentials for households in a bad month.', 'Hàng xóm ở Hà Nội chung tay chia sẻ nhu yếu phẩm cho các hộ gia đình gặp khó khăn.', 'hanoi', null, null, true, true, '{}'),
  ('0abb73b4-11b2-4be2-972c-82169a5c9043', 'Hanoi Warm Meals Kitchen', 'Bếp ăn ấm áp Hà Nội', 'A volunteer kitchen serving hot meals and packing food parcels in Hanoi.', 'Bếp tình nguyện nấu bữa ăn nóng và đóng gói thực phẩm cho người dân Hà Nội.', 'hanoi', 21.01501, 105.74148, true, true, '{}'),
  ('aae3fd05-b35e-4bd5-9b00-65f828635a3d', 'Hanoi School Supplies Drive', 'Chương trình đồ dùng học tập Hà Nội', 'Getting books, bags and stationery to schoolchildren in Hanoi.', 'Đưa sách vở, cặp và dụng cụ học tập đến học sinh ở Hà Nội.', 'hanoi', null, null, true, true, '{}'),
  ('904ff7b6-c2a9-4000-802a-d39216b11538', 'Hai Phong Youth Volunteers', 'Thanh niên tình nguyện Hải Phòng', 'Student volunteers collecting and sorting donations across Hai Phong.', 'Sinh viên tình nguyện thu gom và phân loại đồ quyên góp trên khắp Hải Phòng.', 'hai-phong', null, null, false, true, '{}'),
  ('d0ad6eb5-3020-4c38-b026-48a576bab2f5', 'Ho Chi Minh City Flood Response Team', 'Đội ứng phó lũ Hồ Chí Minh', 'Pre-positioning blankets, clean water and dry food for flood season in Ho Chi Minh City.', 'Chuẩn bị chăn, nước sạch và thực phẩm khô cho mùa lũ ở Hồ Chí Minh.', 'ho-chi-minh-city', null, null, true, true, '{}'),
  ('1f457a59-6e77-4293-927d-65687fa991e0', 'Ho Chi Minh City Elders Care Group', 'Nhóm chăm sóc người cao tuổi Hồ Chí Minh', 'Supporting older people living alone in Ho Chi Minh City with food, hygiene items and company.', 'Hỗ trợ người cao tuổi sống một mình ở Hồ Chí Minh bằng thực phẩm, vật dụng vệ sinh và sự đồng hành.', 'ho-chi-minh-city', 10.79633, 106.71021, true, true, '{}'),
  ('d79e22e8-f97c-41e5-bacc-ceb142e0ce2a', 'Helping Hands Ho Chi Minh City', 'Bàn tay giúp đỡ Hồ Chí Minh', 'A small local group matching families in Ho Chi Minh City with the household goods they need.', 'Nhóm địa phương kết nối các gia đình ở Hồ Chí Minh với đồ dùng gia đình họ đang cần.', 'ho-chi-minh-city', 10.76648, 106.68866, true, true, '{}'),
  ('8f7a88f1-2648-40d3-b3fc-10be7d2dacdc', 'Nghe An Family Relief Circle', 'Vòng tròn cứu trợ gia đình Nghệ An', 'Helping families in Nghe An recover after storms with food, clothing and bedding.', 'Giúp các gia đình ở Nghệ An phục hồi sau bão với thực phẩm, quần áo và chăn màn.', 'nghe-an', null, null, false, true, '{}'),
  ('58101f34-8827-4f14-b9c5-a7c0314dabc4', 'Phu Tho Health & Hygiene Aid', 'Hỗ trợ y tế và vệ sinh Phú Thọ', 'Hygiene kits and basic supplies for families and clinics in Phu Tho.', 'Bộ vật dụng vệ sinh và nhu yếu phẩm cơ bản cho các gia đình và trạm y tế ở Phú Thọ.', 'phu-tho', null, null, true, true, '{}'),
