-- 3goods: coverage organisations (DECISIONS.md D-070). Run once in the Supabase SQL Editor.
-- 23 fictional organisations spread over provinces in proportion to the map's real community-facility distribution,
-- with their login users and needs; 10 of them sit on real OSM facility coordinates so their map pins show as matched (D-073). Also adds organisations.lat/lng and
-- the facility_interests table. Idempotent (re-running updates the same rows). One transaction.
-- Requires supabase/migration-provinces.sql to have been run (province slugs, unit "items", one-need-per-category index).
-- Generated by scripts/build-coverage-sql.mjs from src/data/coverage.js: edit that, not this.

begin;

-- Map pins <-> organisations (DECISIONS.md D-073). (a) An optional exact position on organisations, so a facility pin can be matched
-- to a registered organisation by distance. (b) A small insert-only table for the "this facility hasn't joined yet" interest form.
alter table organisations add column if not exists lat double precision;
alter table organisations add column if not exists lng double precision;

create table if not exists facility_interests (
  id uuid primary key default gen_random_uuid(),
  osm_type text,
  osm_id text,
  facility_name text not null,
  facility_lat double precision,
  facility_lon double precision,
  contact_name text not null,
  contact text not null,
  locale text,
  created_at timestamptz not null default now()
);
alter table facility_interests enable row level security;
drop policy if exists "public insert only" on facility_interests;
create policy "public insert only" on facility_interests for insert to anon, authenticated with check (true);
-- (no select policy on purpose: the public key can write an interest but cannot read anyone's contact details back)

on conflict (id) do update set name = excluded.name, name_vi = excluded.name_vi, description = excluded.description,
  description_vi = excluded.description_vi, city = excluded.city, lat = excluded.lat, lng = excluded.lng,
  verified = excluded.verified, is_demo = excluded.is_demo;

on conflict (id) do update set name = excluded.name, role = excluded.role, org_id = excluded.org_id;

on conflict (id) do update set org_id = excluded.org_id, category_id = excluded.category_id, priority = excluded.priority,
  quantity = excluded.quantity, unit = excluded.unit, status = excluded.status;

commit;

-- Check afterwards: organisations per province (expect 31 in total, Hanoi 9 first) and how many have coordinates (expect 10)
